var CallingCallRoutingTest = &Operation{
	Area: "calling", Group: "call-routing", Command: "test",
	Summary:     "Test Call Routing",
	Description: "Validates that an incoming call can be routed.\n\nDial plans route calls to on-premises destinations by use of trunks or route groups.\nThey are configured globally for an enterprise and apply to all users, regardless of location.\nA dial plan also specifies the routing choice (trunk or route group) for calls that match any of its dial patterns.\nSpecific dial patterns can be defined as part of your dial plan.\n\nTest call routing requires a full administrator auth token with a scope of `spark-admin:telephony_config_write`.",
	Method:      "POST", Path: "/telephony/config/actions/testCallRouting/invoke", Host: HostWebex,
	Params: []Param{
		{Name: "orgId", In: InQuery, Flag: "org-id", Usage: "Organization in which we are validating a call routing."},
	},
	Body: &Body{Fields: []BodyField{
		{Name: "originatorId", Flag: "originator-id", Type: "string"},
		{Name: "originatorType", Flag: "originator-type", Type: "string"},
		{Name: "destination", Flag: "destination", Type: "string"},
		{Name: "originatorNumber", Flag: "originator-number", Type: "string"},
		{Name: "includeAppliedServices", Flag: "include-applied-services", Type: "bool"},
	}},
}

var CallingCallRoutingGetLgwDialPlanUsageTrunk = &Operation{
	Area: "calling", Group: "call-routing", Command: "get-lgw-dial-plan-usage-trunk",
	Summary:     "Get Local Gateway Dial Plan Usage for a Trunk",
	Description: "Get Local Gateway Dial Plan Usage for a Trunk.\n\nA trunk is a connection between Webex Calling and the premises, which terminates on the premises with a local gateway or other supported device.\nThe trunk can be assigned to a Route Group which is a group of trunks that allow Webex Calling to distribute calls over multiple trunks or to provide redundancy.\n\nRetrieving this information requires a full administrator auth token with a scope of `spark-admin:telephony_config_read`.",
	Method:      "GET", Path: "/telephony/config/premisePstn/trunks/{trunkId}/usageDialPlan", Host: HostWebex,
	Params: []Param{
		{Name: "trunkId", In: InPath, Flag: "trunk-id", Usage: "ID of the trunk."},
		{Name: "orgId", In: InQuery, Flag: "org-id", Usage: "Organization to which the trunk belongs."},
		{Name: "start", In: InQuery, Flag: "start", Usage: "Start at the zero-based offset in the list of matching objects."},
		{Name: "max", In: InQuery, Flag: "max", Usage: "Limit the number of objects returned to this maximum count."},
		{Name: "order", In: InQuery, Flag: "order", Usage: "Order the trunks according to the designated fields.  Available sort fields are `name`, and `locationName`. Sort order is ascending by default"},
		{Name: "name", In: InQuery, Flag: "name", Usage: "Return the list of trunks matching the local gateway names"},
		{Name: "name", In: InQuery, Flag: "name", Usage: "Return the list of trunks matching the local gateway names"},
	},
	Paging: &Paging{},
}

