var CallingLocationCallListDialPatterns = &Operation{
	Area: "calling", Group: "location-call", Command: "list-dial-patterns",
	Summary:     "Read the List of Dial Patterns",
	Description: "List all Dial Patterns for the organization.\n\nDial plans route calls to on-premises destinations by use of trunks or route groups.\nThey are configured globally for an enterprise and apply to all users, regardless of location.\nA dial plan also specifies the routing choice (trunk or route group) for calls that match any of its dial patterns.\nSpecific dial patterns can be defined as part of your dial plan.\n\nRetrieving this list requires a full or read-only administrator auth token with a scope of `spark-admin:telephony_config_read`.",
	Method:      "GET", Path: "/telephony/config/premisePstn/dialPlans/{dialPlanId}/dialPatterns", Host: HostWebex,
	Params: []Param{
		{Name: "dialPlanId", In: InPath, Flag: "dial-plan-id", Usage: "ID of the dial plan."},
		{Name: "orgId", In: InQuery, Flag: "org-id", Usage: "ID of the organization to which the dial patterns belong."},
		{Name: "dialPattern", In: InQuery, Flag: "dial-pattern", Usage: "An enterprise dial pattern is represented by a sequence of digits (1-9), followed by optional wildcard characters.\nValid wildcard characters are `!` (matches any sequence of digits) and `X` (matches a single digit, 0-9).\nThe `!` wildcard can only occur once at the end and only in an E.164 pattern\n"},
		{Name: "max", In: InQuery, Flag: "max", Usage: "Limit the number of objects returned to this maximum count."},
		{Name: "start", In: InQuery, Flag: "start", Usage: "Start at the zero-based offset in the list of matching objects."},
		{Name: "order", In: InQuery, Flag: "order", Usage: "Order the dial patterns according to the designated fields.  Available sort fields: `dialPattern`."},
	},
	Paging: &Paging{},
}

