var CallingConvergedRecordingsList = &Operation{
	Area: "calling", Group: "converged-recordings", Command: "list",
	Summary:     "List Recordings",
	Description: "List recordings. You can specify a date range, and the maximum number of recordings to return.\n\nThe list returned is sorted in descending order by the date and time that the recordings were created.\n\nLong result sets are split into [pages](/docs/basics#pagination).\n\nList recordings requires the `spark:recordings_read` scope.\n\nPlease use `List Recordings for Admin or Compliance Officer` API to list all recordings for a user with the role Compliance officer or Admin\n\nRequest Header\n\n* `timezone`: *[Time zone](https://en.wikipedia.org/wiki/List_of_tz_database_time_zones#List) in conformance with the [IANA time zone database](https://www.iana.org/time-zones). The default is UTC if `timezone` is not defined.*",
	Method:      "GET", Path: "/convergedRecordings", Host: HostWebex,
	Params: []Param{
		{Name: "max", In: InQuery, Flag: "max", Usage: "Maximum number of recordings to return in a single page. `max` must be equal to or greater than `1` and equal to or less than `100`."},
		{Name: "from", In: InQuery, Flag: "from", Usage: "Starting date and time (inclusive) for recordings to return, in any [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) compliant format. `from` cannot be after `to`."},
		{Name: "to", In: InQuery, Flag: "to", Usage: "Ending date and time (exclusive) for List recordings to return, in any [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) compliant format. `to` cannot be before `from`."},
		{Name: "status", In: InQuery, Flag: "status", Usage: "Recording's status. If not specified or `available`, retrieves recordings that are available. Otherwise, if specified as `deleted`, retrieves recordings that have been moved into the recycle bin."},
		{Name: "serviceType", In: InQuery, Flag: "service-type", Usage: "Recording's service-type. If specified, the API filters recordings by service-type. Valid values are `calling` and `customerAssist`."},
		{Name: "format", In: InQuery, Flag: "format", Usage: "Recording's file format. If specified, the API filters recordings by format. Valid values are `MP3`."},
		{Name: "ownerType", In: InQuery, Flag: "owner-type", Usage: "Recording based on type of user."},
		{Name: "storageRegion", In: InQuery, Flag: "storage-region", Usage: "Recording stored in certain Webex locations."},
		{Name: "locationId", In: InQuery, Flag: "location-id", Usage: "Fetch recordings for users in a particular Webex Calling location (as configured in Control Hub)."},
		{Name: "topic", In: InQuery, Flag: "topic", Usage: "Recording's topic. If specified, the API filters recordings by topic in a case-insensitive manner."},
		{Name: "timezone", In: InHeader, Flag: "timezone", Usage: "e.g. UTC"},
	},
	Paging:    &Paging{Offset: &OffsetPaging{Start: "", Size: "max", First: 0}},
	TimeRange: TimeISO,
}

var CallingConvergedRecordingsListAdminComplianceOfficer = &Operation{
	Area: "calling", Group: "converged-recordings", Command: "list-admin-compliance-officer",
	Summary:     "List Recordings for Admin or Compliance officer",
	Description: "List recordings for an admin or compliance officer. You can specify a date range, and the maximum number of recordings to return.\n\nThe list returned is sorted in descending order by the date and time that the recordings were created.\n\nLong result sets are split into [pages](/docs/basics#pagination).\n\nList recordings requires the `spark-compliance:recordings_read` scope for compliance officer and `spark-admin:recordings_read` scope for admin.\n\n#### Request Header\n\n* `timezone`: *[Time zone](https://en.wikipedia.org/wiki/List_of_tz_database_time_zones#List) in conformance with the [IANA time zone database](https://www.iana.org/time-zones). The default is UTC if `timezone` is not defined.*",
	Method:      "GET", Path: "/admin/convergedRecordings", Host: HostWebex,
	Params: []Param{
		{Name: "max", In: InQuery, Flag: "max", Usage: "Maximum number of recordings to return in a single page. `max` must be equal to or greater than `1` and equal to or less than `100`."},
		{Name: "from", In: InQuery, Flag: "from", Usage: "Starting date and time (inclusive) for recordings to return, in any [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) compliant format. `from` cannot be after `to`. The interval between `from` and `to` must be within 30 days."},
		{Name: "to", In: InQuery, Flag: "to", Usage: "Ending date and time (exclusive) for List recordings to return, in any [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) compliant format. `to` cannot be before `from`. The interval between `from` and `to` must be within 30 days."},
		{Name: "status", In: InQuery, Flag: "status", Usage: "Recording's status. If not specified or `available`, retrieves recordings that are available. if specified as `purged`, retrieves recordings those are deleted but available to a compliance officer. Otherwise, if specified as `deleted`, retrieves recordings that have been moved into the recycle bin."},
		{Name: "serviceType", In: InQuery, Flag: "service-type", Usage: "Recording's service-type. If specified, the API filters recordings by service-type. Valid values are `calling` and `customerAssist`."},
		{Name: "format", In: InQuery, Flag: "format", Usage: "Recording's file format. If specified, the API filters recordings by format. Valid values are `MP3`."},
		{Name: "ownerId", In: InQuery, Flag: "owner-id", Usage: "Webex user Id to fetch recordings for a particular user."},
		{Name: "ownerEmail", In: InQuery, Flag: "owner-email", Usage: "Webex email address to fetch recordings for a particular user."},
		{Name: "ownerType", In: InQuery, Flag: "owner-type", Usage: "Recording based on type of user."},
		{Name: "storageRegion", In: InQuery, Flag: "storage-region", Usage: "Recording stored in certain Webex locations."},
		{Name: "locationId", In: InQuery, Flag: "location-id", Usage: "Fetch recordings for users in a particular Webex Calling location (as configured in Control Hub)."},
		{Name: "topic", In: InQuery, Flag: "topic", Usage: "Recording's topic. If specified, the API filters recordings by topic in a case-insensitive manner."},
		{Name: "timezone", In: InHeader, Flag: "timezone", Usage: "e.g. UTC"},
	},
	Paging:    &Paging{Offset: &OffsetPaging{Start: "", Size: "max", First: 0}},
	TimeRange: TimeISO,
}

var CallingConvergedRecordingsGet = &Operation{
	Area: "calling", Group: "converged-recordings", Command: "get",
	Summary:     "Get Recording Details",
	Description: "Retrieves details for a recording with a specified recording ID.\n\nOnly recordings of owner with the authenticated user may be retrieved.\n\nGet Recording Details requires the `spark-compliance:recordings_read` scope for compliance officer, `spark-admin:recordings_read` scope for admin and `spark:recordings_read` scope for user.\n\n#### Request Header\n\n* `timezone`: *[Time zone](https://en.wikipedia.org/wiki/List_of_tz_database_time_zones#List) in conformance with the [IANA time zone database](https://www.iana.org/time-zones). The default is UTC if `timezone` is not defined.*",
	Method:      "GET", Path: "/convergedRecordings/{recordingId}", Host: HostWebex,
	Params: []Param{
		{Name: "recordingId", In: InPath, Flag: "recording-id", Usage: "A unique identifier for the recording."},
		{Name: "timezone", In: InHeader, Flag: "timezone", Usage: "e.g. UTC"},
	},
}

var CallingConvergedRecordingsDelete = &Operation{
	Area: "calling", Group: "converged-recordings", Command: "delete",
	Summary:     "Delete a Recording",
	Description: "Removes a recording with a specified recording ID. The deleted recording cannot be recovered.\n\nIf a Compliance Officer deletes another user's recording, the recording will be inaccessible to regular users (host, attendees and shared), and to the Compliance officer as well. This action purges the recordings from Webex.\n\nDelete a Recording requires the `spark-compliance:recordings_write` scope.",
	Method:      "DELETE", Path: "/convergedRecordings/{recordingId}", Host: HostWebex,
	Params: []Param{
		{Name: "recordingId", In: InPath, Flag: "recording-id", Usage: "A unique identifier for the recording."},
	},
	Body: &Body{Fields: []BodyField{
		{Name: "reason", Flag: "reason", Type: "string"},
		{Name: "comment", Flag: "comment", Type: "string"},
	}},
}

var CallingConvergedRecordingsGetMetadata = &Operation{
	Area: "calling", Group: "converged-recordings", Command: "get-metadata",
	Summary:     "Get Recording metadata",
	Description: "Retrieves metadata details for a recording with a specified recording ID. The recording must be owned by the authenticated user.\n\nFor information on the metadata fields, refer to [Metadata Guide](https://developer.webex.com/docs/api/guides/consolidated-metadata-documentation-and-samples-guide)\n\nGet Recording metadata requires the `spark-compliance:recordings_read` scope for compliance officer, `spark-admin:recordings_read` for admin and `spark:recordings_read` for user.",
	Method:      "GET", Path: "/convergedRecordings/{recordingId}/metadata", Host: HostWebex,
	Params: []Param{
		{Name: "recordingId", In: InPath, Flag: "recording-id", Usage: "A unique identifier for the recording."},
		{Name: "showAllTypes", In: InQuery, Flag: "show-all-types", Usage: "If `showAllTypes` is `true`, all attributes will be shown. If it's `false` or not specified, the following attributes of the metadata will be hidden.\n                                          serviceData.callActivity.mediaStreams\n                                          serviceData.callActivity.participants\n                                          serviceData.callActivity.redirectInfo\n                                          serviceData.callActivity.redirectedCall\n"},
	},
}

var CallingConvergedRecordingsReassign = &Operation{
	Area: "calling", Group: "converged-recordings", Command: "reassign",
	Summary:     "Reassign Recordings",
	Description: "Reassigns recordings to a new user. As an administrator, you can reassign a list of recordings or all recordings of a particular user to a new user.\nThe recordings can belong to an org user, a virtual line, or a workspace, but the destination user should only be a valid org user.\n\n* For a org user either `ownerEmail` or `recordingIds` or both must be provided.\n\n* For a virtual line or a workspace, `ownerID` or `recordingIds` or both must be provided.\n\n* If `recordingIds` and `ownerID` is empty but `ownerEmail` is provided, all recordings owned by the `ownerEmail` are reassigned to `reassignOwnerEmail`.\n\n* If `recordingIds` is provided and `ownerEmail` or `ownerID` is also provided, only the recordings specified by `recordingIds` that are owned by `ownerEmail` or `ownerID` are reassigned to `reassignOwnerEmail`.\n\n* If `ownerEmail` and `ownerID` is empty but `recordingIds` is provided, the recordings specified by `recordingIds` are reassigned to `reassignOwnerEmail` regardless of the current owner.\n\n* If both `ownerId` and `ownerEmail` are passed along with `recordingIds`, only the recordings specified by `recordingIds` that are owned by `ownerEmail` are reassigned to `reassignOwnerEmail`.\n\n* If `recordingIds` is empty but both `ownerId` and `ownerEmail` is provided, all recordings owned by the `ownerEmail` are reassigned to `reassignOwnerEmail`.\n\nThe `spark-admin:recordings_write` scope is required to reassign recordings.",
	Method:      "POST", Path: "/convergedRecordings/reassign", Host: HostWebex,
	Body: &Body{Fields: []BodyField{
		{Name: "reassignOwnerEmail", Flag: "reassign-owner-email", Type: "string"},
		{Name: "ownerEmail", Flag: "owner-email", Type: "string"},
		{Name: "ownerID", Flag: "owner-id", Type: "string"},
		{Name: "recordingIds", Flag: "recording-ids", Type: "[]string"},
	}},
}

var CallingConvergedRecordingsMoveRecycleBin = &Operation{
	Area: "calling", Group: "converged-recordings", Command: "move-recycle-bin",
	Summary:     "Move Recordings into the Recycle Bin",
	Description: "Move recordings into the recycle bin with recording IDs or move all the recordings to the recycle bin.\n\nOnly the following two entities can use this API\n\n* Administrator: A user or an application with the scope `spark-admin:recordings_write`.\n\n* User: An authenticated user who does not have the scope `spark-admin:recordings_write` but has `spark:recordings_write`.\n\nAs an `administrator`, you can move a list of recordings or all recordings of a particular user within the org you manage to the recycle bin.\n\nAs a `user`, you can move a list of your own recordings or all your recordings to the recycle bin.\n\nRecordings in the recycle bin can be recovered by [Restore Recordings from Recycle Bin](/docs/api/v1/converged-recordings/restore-recordings-from-recycle-bin) API. If you'd like to empty recordings from the recycle bin, you can use [Purge Recordings from Recycle Bin](/docs/api/v1/converged-recordings/purge-recordings-from-recycle-bin) API to purge all or some of them.\n\n* If `trashAll` is `true`:\n  * `recordingIds` should be empty.\n  * If the caller of this API is an `administrator`, `ownerEmail` should not be empty and all recordings owned by the `ownerEmail` will be moved to the recycle bin.\n  * If the caller of this API is a `user`, `ownerEmail` should be empty and all recordings owned by the caller will be moved to the recycle bin.\n\n* If `trashAll` is `false`:\n  * `ownerEmail` should be empty.\n  * `recordingIds` should not be empty and its maximum size is `100`.",
	Method:      "POST", Path: "/convergedRecordings/softDelete", Host: HostWebex,
	Body: &Body{Fields: []BodyField{
		{Name: "trashAll", Flag: "trash-all", Type: "bool"},
		{Name: "ownerEmail", Flag: "owner-email", Type: "string"},
		{Name: "recordingIds", Flag: "recording-ids", Type: "[]string"},
	}},
}

var CallingConvergedRecordingsRestoreRecycleBin = &Operation{
	Area: "calling", Group: "converged-recordings", Command: "restore-recycle-bin",
	Summary:     "Restore Recordings from Recycle Bin",
	Description: "Restore recordings from the recycle bin with recording IDs or restore all the recordings that are in the recycle bin.\n\nOnly the following two entities can use this API\n\n* Administrator: A user or an application with the scope `spark-admin:recordings_write`.\n\n* User: An authenticated user who does not have the scope `spark-admin:recordings_write` but has `spark:recordings_write`.\n\nAs an `administrator`, you can restore a list of recordings or all recordings of a particular user within the org you manage from the recycle bin.\n\nAs a `user`, you can restore a list of your own recordings or all your recordings from the recycle bin.\n\n* If `restoreAll` is `true`:\n  * `recordingIds` should be empty.\n  * If the caller of this API is an `administrator`, `ownerEmail` should not be empty and all recordings owned by the `ownerEmail` will be restored from the recycle bin.\n  * If the caller of this API is a `user`, `ownerEmail` should be empty and all recordings owned by the caller will be restored from the recycle bin.\n\n* If `restoreAll` is `false`:\n  * `ownerEmail` should be empty.\n  * `recordingIds` should not be empty and its maximum size is `100`.",
	Method:      "POST", Path: "/convergedRecordings/restore", Host: HostWebex,
	Body: &Body{Fields: []BodyField{
		{Name: "restoreAll", Flag: "restore-all", Type: "bool"},
		{Name: "ownerEmail", Flag: "owner-email", Type: "string"},
		{Name: "recordingIds", Flag: "recording-ids", Type: "[]string"},
	}},
}

var CallingConvergedRecordingsPurgeRecycleBin = &Operation{
	Area: "calling", Group: "converged-recordings", Command: "purge-recycle-bin",
	Summary:     "Purge Recordings from Recycle Bin",
	Description: "Purge recordings from the recycle bin matching the supplied recording IDs, or purge all the recordings that are in the recycle bin. A recording, once purged, cannot be restored.\n\nOnly the following two entities can use this API\n\n* Administrator: A user or an application with the scope `spark-admin:recordings_write`.\n\n* User: An authenticated user who does not have the scope `spark-admin:recordings_write` but has `spark:recordings_write`.\n\nAs an `administrator`, you can purge a list of recordings or all recordings of a particular user within the org you manage from the recycle bin.\n\nAs a `user`, you can purge a list of your own recordings or all your recordings from the recycle bin.\n\n* If `purgeAll` is `true`:\n  * `recordingIds` should be empty.\n  * If the caller of this API is an `administrator`, `ownerEmail` should not be empty and all recordings owned the `ownerEmail` will be purged from the recycle bin.\n  * If the caller of this API is a `user`, `ownerEmail` should be empty and all recordings owned by the caller will be purged from the recycle bin.\n\n* If `purgeAll` is `false`:\n  * `ownerEmail` should be empty.\n  * `recordingIds` should not be empty and its maximum size is `100`.",
	Method:      "POST", Path: "/convergedRecordings/purge", Host: HostWebex,
	Body: &Body{Fields: []BodyField{
		{Name: "purgeAll", Flag: "purge-all", Type: "bool"},
		{Name: "ownerEmail", Flag: "owner-email", Type: "string"},
		{Name: "recordingIds", Flag: "recording-ids", Type: "[]string"},
	}},
}

