var CallingEmergencyServicesGetOrgCallNotification = &Operation{
	Area: "calling", Group: "emergency-services", Command: "get-org-call-notification",
	Summary:     "Get an Organization Emergency Call Notification",
	Description: "Get organization emergency call notification.\n\nEmergency Call Notifications can be enabled at the organization level, allowing specified email addresses to receive email notifications when an emergency call is made. To comply with U.S. Public Law 115-127, also known as Kari’s Law, any call that's made from within your organization to emergency services must generate an email notification.\n\nTo retrieve organization call notifications requires a full, user or read-only administrator auth token with a scope of `spark-admin:telephony_config_read`.",
	Method:      "GET", Path: "/telephony/config/emergencyCallNotification", Host: HostWebex,
	Params: []Param{
		{Name: "orgId", In: InQuery, Flag: "org-id", Usage: "Retrieve Emergency Call Notification attributes for the organization."},
	},
}

var CallingEmergencyServicesUpdateOrgCallNotification = &Operation{
	Area: "calling", Group: "emergency-services", Command: "update-org-call-notification",
	Summary:     "Update an Organization Emergency Call Notification",
	Description: "Update an organization emergency call notification.\n\nOnce settings are enabled at the organization level, the configured email address will receive emergency call notifications for all locations.\n\nEmergency Call Notifications can be enabled at the organization level, allowing specified email addresses to receive email notifications when an emergency call is made. To comply with U.S. Public Law 115-127, also known as Kari’s Law, any call that's made from within your organization to emergency services must generate an email notification.\n\nTo update organization call notification requires a full or user administrator auth token with a scope of `spark-admin:telephony_config_write`.",
	Method:      "PUT", Path: "/telephony/config/emergencyCallNotification", Host: HostWebex,
	Params: []Param{
		{Name: "orgId", In: InQuery, Flag: "org-id", Usage: "Update Emergency Call Notification attributes for the organization."},
	},
	Body: &Body{Fields: []BodyField{
		{Name: "emergencyCallNotificationEnabled", Flag: "emergency-call-notification-enabled", Type: "bool"},
		{Name: "allowEmailNotificationAllLocationEnabled", Flag: "allow-email-notification-all-location-enabled", Type: "bool"},
		{Name: "emailAddress", Flag: "email-address", Type: "string"},
	}},
}

