var CallingCallQueueListCustomerAssist = &Operation{
	Area: "calling", Group: "call-queue", Command: "list-customer-assist",
	Summary:     "Read the List of Call Queues with Customer Assist",
	Description: "List all Call Queues for the organization.\n\nCall queues temporarily hold calls in the cloud, when all agents\nassigned to receive calls from the queue are unavailable. Queued calls are routed to \nan available agent, when not on an active call. Each call queue is assigned a lead number, which is a telephone\nnumber that external callers can dial to reach the users assigned to the call queue.\nCall queues are also assigned an internal extension, which can be dialed\ninternally to reach the users assigned to the call queue.\n\nRetrieving this list requires a full or read-only administrator auth token with a scope of `spark-admin:telephony_config_read`.",
	Method:      "GET", Path: "/telephony/config/queues", Host: HostWebex,
	Params: []Param{
		{Name: "orgId", In: InQuery, Flag: "org-id", Usage: "Returns the list of call queues in this organization."},
		{Name: "locationId", In: InQuery, Flag: "location-id", Usage: "Returns the list of call queues in this location."},
		{Name: "max", In: InQuery, Flag: "max", Usage: "Limit the number of objects returned to this maximum count."},
		{Name: "start", In: InQuery, Flag: "start", Usage: "Start at the zero-based offset in the list of matching objects."},
		{Name: "name", In: InQuery, Flag: "name", Usage: "Returns only the call queues matching the given name."},
		{Name: "phoneNumber", In: InQuery, Flag: "phone-number", Usage: "Returns only the call queues matching the given primary phone number or extension."},
		{Name: "departmentId", In: InQuery, Flag: "department-id", Usage: "Returns only call queues matching the given department ID."},
		{Name: "departmentName", In: InQuery, Flag: "department-name", Usage: "Returns only call queues matching the given department name."},
		{Name: "hasCxEssentials", In: InQuery, Flag: "has-cx-essentials", Usage: "Returns only the list of call queues with Customer Assist license when `true`, otherwise returns the list of Customer Experience Basic call queues."},
	},
	Paging: &Paging{},
}

