var CallingWorkspaceCallUpdateInterceptSettings = &Operation{
	Area: "calling", Group: "workspace-call", Command: "update-intercept-settings",
	Summary:     "Configure Call Intercept Settings for a Workspace",
	Description: "Configures a Workspace's Call Intercept Settings\n\nThe intercept feature gracefully takes a workspace's phone out of service, while providing callers with informative announcements and alternative routing options. Depending on the service configuration, none, some, or all incoming calls to the specified person are intercepted. Also depending on the service configuration, outgoing calls are intercepted or rerouted to another location.\n\nThis API requires a full or read-only administrator or location administrator auth token with a scope of `spark-admin:workspaces_write` or a user auth token with `spark:workspaces_read` scope can be used by a person to read their settings.",
	Method:      "PUT", Path: "/workspaces/{workspaceId}/features/intercept", Host: HostWebex,
	Params: []Param{
		{Name: "workspaceId", In: InPath, Flag: "workspace-id", Usage: "Unique identifier for the workspace."},
		{Name: "orgId", In: InQuery, Flag: "org-id", Usage: "ID of the organization within which the workspace resides. Only admin users of another organization (such as partners) may use this parameter as the default is the same organization as the token used to access the API."},
	},
	Body: &Body{},
}

var CallingWorkspaceCallGetTransferNumbersSettings = &Operation{
	Area: "calling", Group: "workspace-call", Command: "get-transfer-numbers-settings",
	Summary:     "Retrieve Transfer Numbers Settings for a Workspace",
	Description: "Retrieve Transfer Numbers Settings for a Workspace.\n\nWhen calling a specific call type, this workspace will be automatically transferred to another number. The person assigned the Auto Transfer Number can then approve the call and send it through or reject the call type. You can add up to 3 numbers.\n\nThis API requires a full or read-only administrator or location administrator auth token with a scope of `spark-admin:workspaces_read` or a user auth token with `spark:workspaces_read` scope can be used to read workspace settings.",
	Method:      "GET", Path: "/workspaces/{workspaceId}/features/outgoingPermission/autoTransferNumbers", Host: HostWebex,
	Params: []Param{
		{Name: "workspaceId", In: InPath, Flag: "workspace-id", Usage: "Unique identifier for the workspace."},
		{Name: "orgId", In: InQuery, Flag: "org-id", Usage: "ID of the organization within which the workspace resides. Only admin users of another organization (such as partners) may use this parameter as the default is the same organization as the token used to access the API."},
	},
}

