var CallingWorkspaceCallGetFaxAvailableNumbers = &Operation{
	Area: "calling", Group: "workspace-call", Command: "get-fax-available-numbers",
	Summary:     "Get Workspace Fax Message Available Phone Numbers",
	Description: "List standard numbers that are available to be assigned as a workspace's FAX message number.\nThese numbers are associated with the location of the workspace specified in the request URL, can be active or inactive, and are unassigned.\n\nThe available numbers APIs help identify candidate numbers and their owning entities to simplify the assignment or association of these numbers to members or features.\n\nRetrieving this list requires a full, read-only or location administrator auth token with a scope of `spark-admin:telephony_config_read`.\n\n<div><Callout type=\"info\">Only available for workspaces with the professional license entitlement.</Callout></div>",
	Method:      "GET", Path: "/telephony/config/workspaces/{workspaceId}/faxMessage/availableNumbers", Host: HostWebex,
	Params: []Param{
		{Name: "workspaceId", In: InPath, Flag: "workspace-id", Usage: "Unique identifier for the workspace."},
		{Name: "orgId", In: InQuery, Flag: "org-id", Usage: "List numbers for this organization."},
		{Name: "max", In: InQuery, Flag: "max", Usage: "Limit the number of phone numbers returned to this maximum count. The default is 2000."},
		{Name: "start", In: InQuery, Flag: "start", Usage: "Start at the zero-based offset in the list of matching phone numbers. The default is 0."},
		{Name: "phoneNumber", In: InQuery, Flag: "phone-number", Usage: "Filter phone numbers based on the comma-separated list provided in the `phoneNumber` array."},
		{Name: "phoneNumber", In: InQuery, Flag: "phone-number", Usage: "Filter phone numbers based on the comma-separated list provided in the `phoneNumber` array."},
	},
	Paging: &Paging{},
}

